def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    current = []
    balance = 0
    for char in paren_string:
        if char == '(':
            balance += 1
            current.append(char)
        elif char == ')':
            balance -= 1
            current.append(char)
            if balance == 0:
                result.append("".join(current))
                current = []
    return result

